<script>
(function(){
  'use strict';
  var form=document.getElementById('requestWizard');
  var family=document.getElementById('service_family');
  var category=document.getElementById('service_category');
  var serviceHelp=document.getElementById('serviceHelp');
  var panels=Array.prototype.slice.call(document.querySelectorAll('.panel'));
  var navs=Array.prototype.slice.call(document.querySelectorAll('.stepnav'));
  var current=1;
  var allServiceOptions=Array.prototype.slice.call(category.querySelectorAll('option[data-family]')).map(function(o){return {value:o.value,text:o.textContent,family:o.getAttribute('data-family')};});

  function filterServices(preserve){
    var selectedFamily=family.value;
    var previous=preserve?category.value:'';
    category.innerHTML='';
    var placeholder=document.createElement('option'); placeholder.value=''; placeholder.textContent=@json($c['choose']); category.appendChild(placeholder);
    allServiceOptions.forEach(function(item){
      if(!selectedFamily || item.family===selectedFamily){var opt=document.createElement('option');opt.value=item.value;opt.textContent=item.text;opt.setAttribute('data-family',item.family);category.appendChild(opt);}
    });
    if(previous && Array.prototype.some.call(category.options,function(o){return o.value===previous;})){category.value=previous;}
    serviceHelp.classList.toggle('show',!!selectedFamily && category.options.length<=1);
  }

  function syncRequestType(){
    var intent=document.querySelector('input[name="request_intent"]:checked');
    if(!intent)return;
    document.getElementById('request_type').value=intent.value==='QUOTATION'?'QUOTATION':'SERVICE_REQUEST';
  }

  function validatePanel(step){
    var panel=document.querySelector('.panel[data-step="'+step+'"]');
    var fields=Array.prototype.slice.call(panel.querySelectorAll('input,select,textarea')).filter(function(el){return el.required && !el.disabled;});
    for(var i=0;i<fields.length;i++){
      if(!fields[i].checkValidity()){fields[i].reportValidity();fields[i].focus();return false;}
    }
    return true;
  }

  function showStep(step){
    current=Math.max(1,Math.min(4,step));
    panels.forEach(function(p){p.classList.toggle('active',Number(p.getAttribute('data-step'))===current);});
    navs.forEach(function(n){var s=Number(n.getAttribute('data-stepnav'));n.classList.toggle('active',s===current);n.classList.toggle('done',s<current);});
    if(current===4)buildReview();
    window.scrollTo({top:Math.max(0,document.querySelector('.wizard').offsetTop-20),behavior:'smooth'});
  }

  function textOfSelect(id){var el=document.getElementById(id);return el&&el.selectedIndex>=0?el.options[el.selectedIndex].text:'—';}
  function buildReview(){
    var intent=document.querySelector('input[name="request_intent"]:checked');
    document.getElementById('reviewIntent').textContent=intent?intent.parentElement.querySelector('b').textContent:'—';
    document.getElementById('reviewService').textContent=textOfSelect('service_family')+' · '+textOfSelect('service_category');
    document.getElementById('reviewCity').textContent=textOfSelect('site_city');
    var urgency=document.querySelector('input[name="urgency"]:checked');document.getElementById('reviewUrgency').textContent=urgency?urgency.parentElement.querySelector('span').textContent:'—';
    document.getElementById('reviewSubject').textContent=document.getElementById('subject').value||'—';
    document.getElementById('reviewContact').textContent=(document.getElementById('company_name').value||'—')+' · '+(document.getElementById('responsible_person').value||'—');
  }

  family.addEventListener('change',function(){filterServices(false);});
  category.addEventListener('change',function(){serviceHelp.classList.remove('show');});
  Array.prototype.forEach.call(document.querySelectorAll('input[name="request_intent"]'),function(r){r.addEventListener('change',syncRequestType);});
  Array.prototype.forEach.call(document.querySelectorAll('.next'),function(btn){btn.addEventListener('click',function(){syncRequestType();if(validatePanel(current))showStep(current+1);});});
  Array.prototype.forEach.call(document.querySelectorAll('.prev'),function(btn){btn.addEventListener('click',function(){showStep(current-1);});});
  form.addEventListener('submit',function(e){syncRequestType();if(!validatePanel(3)){e.preventDefault();showStep(3);}});

  filterServices(true); syncRequestType(); showStep(1);
})();
</script></body></html>
